/// Eight-second, 320x180 H.264 constrained-baseline fMP4 generated with the
/// imageio-ffmpeg 0.6.0 FFmpeg 7.1 binary and x264 core 164 r3190 7ed753b.
/// The full command, with arguments continued in order, was:
/// `ffmpeg -hide_banner -y -f lavfi`
/// `-i testsrc=size=320x180:rate=30:duration=8 -an -c:v libx264`
/// `-profile:v baseline -level:v 3.0 -pix_fmt yuv420p -preset veryslow`
/// `-crf 38 -g 30 -keyint_min 30 -sc_threshold 0 -bf 0 -f hls`
/// `-hls_time 1 -hls_playlist_type vod -hls_segment_type fmp4`
/// `-hls_fmp4_init_filename init.mp4`
/// `-hls_segment_filename index%d.m4s index.m3u8`
final class DeterministicHlsFixture {
  static final Map<String, Uint8List> assets = _decodeAssets();

  static const playlist = '''#EXTM3U
#EXT-X-VERSION:7
#EXT-X-TARGETDURATION:1
#EXT-X-MEDIA-SEQUENCE:0
#EXT-X-PLAYLIST-TYPE:VOD
#EXT-X-MAP:URI="init.mp4"
#EXTINF:1.000000,
index0.m4s
#EXTINF:1.000000,
index1.m4s
#EXTINF:1.000000,
index2.m4s
#EXTINF:1.000000,
index3.m4s
#EXTINF:1.000000,
index4.m4s
#EXTINF:1.000000,
index5.m4s
#EXTINF:1.000000,
index6.m4s
#EXTINF:1.000000,
index7.m4s
#EXT-X-ENDLIST
''';
}

Map<String, Uint8List> _decodeAssets() {
  final bundle = Uint8List.fromList(gzip.decode(base64Decode(_fixtureBundle)));
  final assets = <String, Uint8List>{};
  var offset = 0;
  for (var index = 0; index < _fixtureNames.length; index += 1) {
    final end = offset + _fixtureLengths[index];
    assets[_fixtureNames[index]] = Uint8List.sublistView(bundle, offset, end);
    offset = end;
  }
  return Map<String, Uint8List>.unmodifiable(assets);
}

const _fixtureNames = [
  'init.mp4',
  'index0.m4s',
  'index1.m4s',
  'index2.m4s',
  'index3.m4s',
  'index4.m4s',
  'index5.m4s',
  'index6.m4s',
  'index7.m4s',
];

const _fixtureLengths = [810, 5057, 4444, 4641, 4625, 4520, 4661, 4612, 4242];

const _fixtureBundle =
    '';
